# src/depdelta_cli/gerrit.py
#
# The review as a Gerrit change message on the patch set, with no vote. The
# `autogenerated:` tag lets Gerrit's UI fold earlier patch sets' reviews
# away behind "Show all comments" ("Only comments" hides them).

from depdelta_cli import web
from depdelta_cli.env import GerritChange

TAG = "autogenerated:depdelta"
#: Gerrit's default change.commentSizeLimit is 16 KiB.
MAX_MESSAGE = 16_000


class GerritError(Exception):
    """Gerrit refused the message."""


def fit(message: str, link: str | None = None) -> str:
    """``message`` cut to Gerrit's size limit, ending with ``link``."""
    if len(message) <= MAX_MESSAGE:
        return message
    tail = f"\n\n… cut to fit. The full review: {link}" if link else "\n\n…"
    return message[: MAX_MESSAGE - len(tail)].rstrip() + tail


def post(change: GerritChange, message: str, user: str, password: str) -> None:
    """Post ``message`` on the change's patch set (HTTP password auth)."""
    url = (
        f"{change.url}/a/changes/{change.change_id}/revisions/{change.revision}/review"
    )
    reply = web.request(
        "POST",
        url,
        body={"message": message, "tag": TAG, "notify": "OWNER"},
        headers={"Authorization": web.basic(user, password)},
    )
    if reply.status != 200:
        detail = reply.body if isinstance(reply.body, str) else ""
        raise GerritError(f"Gerrit answered {reply.status}: {detail[:300]}".strip())
